package com.example.leetcodetrainer.adaptive.service;
import com.example.leetcodetrainer.adaptive.domain.*; import com.example.leetcodetrainer.attempt.domain.StageType; import java.util.*; import org.springframework.stereotype.Service;
@Service public class ReasoningProfileService { public List<ProfileStageDefinition> stagesFor(ReasoningProfileType p){ if(p==ReasoningProfileType.RECURSIVE_DIVIDE_AND_COMBINE)return List.of(new ProfileStageDefinition(p,StageType.PROBLEM_RELATION,StageApplicability.REQUIRED,"再帰関数の契約","この関数は何を返しますか？",List.of(),1),new ProfileStageDefinition(p,StageType.RESOLUTION_EVENT,StageApplicability.REQUIRED,"最小入力と答え","これ以上分解できない最小入力と答えは何ですか？",List.of(),2),new ProfileStageDefinition(p,StageType.UPDATED_REGION,StageApplicability.REQUIRED,"同じ形の部分問題","どの小さい同型問題に分けますか？",List.of(),3),new ProfileStageDefinition(p,StageType.UNRESOLVED_STATE,StageApplicability.REQUIRED,"子から受け取る情報","各部分問題は何を返しますか？",List.of(),4),new ProfileStageDefinition(p,StageType.REQUIRED_OPERATIONS,StageApplicability.REQUIRED,"子の答えの合成","子の答えを現在のnodeでどう組み合わせますか？",List.of(),5),new ProfileStageDefinition(p,StageType.BRUTE_FORCE,StageApplicability.OPTIONAL,"最も直接的な正しい方法","最も単純な方法は何ですか？",List.of(),6),new ProfileStageDefinition(p,StageType.INVARIANT,StageApplicability.REQUIRED,"各呼び出しが保証すること","各呼び出しの戻り値は何を保証しますか？",List.of(),7),new ProfileStageDefinition(p,StageType.CORRECTNESS_AND_COMPLEXITY,StageApplicability.REQUIRED,"再帰が正しい理由","なぜ部分問題の合成で正しいですか？",List.of(),8),new ProfileStageDefinition(p,StageType.IMPLEMENTATION,StageApplicability.REQUIRED,"実装","契約をコードへ翻訳します。",List.of(),9),new ProfileStageDefinition(p,StageType.TRANSFER,StageApplicability.REQUIRED,"転移","同じ再帰構造を探します。",List.of(),10),new ProfileStageDefinition(p,StageType.REFLECTION,StageApplicability.REQUIRED,"振り返り","次回の手がかりを書きます。",List.of(),11),new ProfileStageDefinition(p,StageType.REPEATED_WORK,StageApplicability.NOT_APPLICABLE,"重複処理","",List.of(),12),new ProfileStageDefinition(p,StageType.DATA_STRUCTURE_SELECTION,StageApplicability.NOT_APPLICABLE,"データ構造選択","",List.of(),13)); return StageType.ordered().stream().map(s->new ProfileStageDefinition(p,s,StageApplicability.REQUIRED,s.getDisplayName(),s.getPrimaryQuestion(),s.getHelperQuestions(),s.getOrder())).toList(); } public ReasoningProfileType profileForSlug(String slug){return "maximum-depth-of-binary-tree".equals(slug)?ReasoningProfileType.RECURSIVE_DIVIDE_AND_COMBINE:ReasoningProfileType.LOOKUP_STATE;} }
